def set_tif_names(directory: Any, file_names: Any) -> object {
    tif_names = [];
    for i in file_names {
        tif_names.append((directory + i + '.tif'));
    }
    return tif_names;
}

"""Rabin-Miller test.

    n should be odd number and 1 < b < n-1.
    """
def spsp(n: Any, a: Any) -> object {
    if ((n % 2) == 0) {
        return False;
    }
    n1 = n - 1;
    d = n1;
    r = 1;
    s = 0;
    while (r != 0) {
        r = d % 2;
        d = d // 2;
        s += 1;
    }
    p = a;
    p = pow(p, d, n);
    if ((p == 1) or (p == n1)) {
        return True;
    }
    for i in range(1, s) {
        p = pow(p, 2, n);
        if (p == n1) {
            return True;
        }
    }
    return False;
}

"""Tries to account for the fact that there's different ways to
    write the name of the same country, and the slugification alone
    doesn't not standardise it. Also, it'll be of help to some spanish users.
    """
def translate_country(country_name: Any) -> object {
    translation_dict = {
        "us": "usa",
        "united-states": "usa",
        "united-states-of-america": "usa",
        "estados-unidos": "usa",
        "eeuu": "usa",
        "united-kingdom": "uk",
        "great-britain": "uk",
        "arg": "argentina",
        "ar": "argentina",
        "brasil": "brazil"
    };
    return translation_dict.get(country_name, country_name);
}

"""
    Trim the url to get the video hoster
    :return vidhost
    """
def get_vidhost(url: Any) -> object {
    parts = url.split('/')[2].split('.');
    vidhost = '%s.%s' % (parts[(len(parts) - 2)], parts[(len(parts) - 1)]);
    return vidhost;
}

""" strip first and last (double) quotes"""
def strip_quotes(string: Any) -> object {
    if (string.startswith('"') and string.endswith('"')) {
        return string[1:-1];
    }
    if (string.startswith("'") and string.endswith("'")) {
        return string[1:-1];
    }
    return string;
}

